package com.fitpulse.model.dto; import com.fitpulse.model.enums.ContentStatus; import jakarta.validation.constraints.*; import java.math.BigDecimal;
public class GymForm { @NotNull(message="Попълнете задължителното поле.") private Long cityId; @NotBlank(message="Попълнете задължителното поле.") @Size(max=150,message="Полето допуска най-много {max} знака.") private String name; @Size(max=3000,message="Полето допуска най-много {max} знака.") private String description; @Size(max=300,message="Полето допуска най-много {max} знака.") private String address; @DecimalMin(value="-90",message="Географската ширина трябва да е между -90 и 90.") @DecimalMax(value="90",message="Географската ширина трябва да е между -90 и 90.") @Digits(integer=3,fraction=6,message="Координатите допускат до шест десетични знака.") private BigDecimal latitude; @DecimalMin(value="-180",message="Географската дължина трябва да е между -180 и 180.") @DecimalMax(value="180",message="Географската дължина трябва да е между -180 и 180.") @Digits(integer=3,fraction=6,message="Координатите допускат до шест десетични знака.") private BigDecimal longitude; @Size(max=50,message="Полето допуска най-много {max} знака.") private String phone; @Size(max=500,message="Полето допуска най-много {max} знака.") private String websiteUrl; @Size(max=1000,message="Полето допуска най-много {max} знака.") private String openingHours; @Size(max=1500,message="Полето допуска най-много {max} знака.") private String services; @Size(max=1000,message="Полето допуска най-много {max} знака.") private String priceInfo; @NotNull(message="Попълнете задължителното поле.") private ContentStatus status=ContentStatus.DRAFT; public Long getCityId(){return cityId;} public void setCityId(Long v){cityId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getWebsiteUrl(){return websiteUrl;} public void setWebsiteUrl(String v){websiteUrl=v;} public String getOpeningHours(){return openingHours;} public void setOpeningHours(String v){openingHours=v;} public String getServices(){return services;} public void setServices(String v){services=v;} public String getPriceInfo(){return priceInfo;} public void setPriceInfo(String v){priceInfo=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;}  @AssertTrue(message="Уебсайтът трябва да бъде валиден HTTP/HTTPS адрес.") public boolean isWebsiteUrlValid(){return com.fitpulse.service.GymContent.webUrl(websiteUrl);} @AssertTrue(message="Попълнете и двете координати или оставете и двете празни.") public boolean isCoordinatesValid(){return (latitude==null)==(longitude==null);} }
